import{_ as o,b as l,c as i,g as n}from"./chunks/framework.86O3EbG5.js";const b=JSON.parse('{"title":"古代汉语","description":"","frontmatter":{"title":"古代汉语","subTitle":"所字结构","author":"oasis","date":"2026-10-20T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/gu-dai-han-yu/1-1.md","filePath":"articles/gu-dai-han-yu/1-1.md"}'),r={name:"articles/gu-dai-han-yu/1-1.md"};function p(s,t,e,g,d,a){return l(),i("div",null,[...t[0]||(t[0]=[n('<h2 id="定义" tabindex="-1">定义</h2><blockquote><p><strong>“所”是一个特殊指示代词，放在动词（或动词性词组）前面，构成「所 + V」，叫做所字结构。所字结构整体是名词性短语，在句子里充当主语、宾语、定语。</strong></p></blockquote><p>核心一句话：<strong>“所 + 动词” ≈ “……的人 / ……的事物 / ……的地方”</strong>。</p><h2 id="一、基本格式" tabindex="-1">一、基本格式</h2><h3 id="_1-所-及物动词" tabindex="-1">1. 所 + 及物动词</h3><p>公式：<strong>所V = 所V的对象</strong>。</p><ul><li>所见 = 看见的东西</li><li>所闻 = 听到的事</li><li>所务 = 致力的事情（上文中：所务兵食而已）</li></ul><p>王力强调：<strong>“所”本身不独立充当句子成分；它必须依附动词，组合之后整个短语才是名词性。</strong></p><p>和者字结构的区别：</p><ul><li><strong>者字结构</strong>是 <strong>V + 者</strong>，指做这个动作的人。见者：看见的人。</li><li><strong>所字结构</strong>是 <strong>所 + V</strong>，指被这个动作涉及的东西。所见：被看见的东西。</li></ul><h3 id="_2-所-动词-者-所-者" tabindex="-1">2. 所 + 动词 + 者（所……者）</h3><p>“者”起复指作用，加强指代，整体仍然名词性。</p><blockquote><p>所与共担纆薪菜者（《九方皋相马》）= 和我一起扛绳打柴的那个人</p></blockquote><h3 id="_3-所-介词-动词" tabindex="-1">3. 所 + 介词 + 动词</h3><p>所从、所由、所以是王力重点。</p><ul><li><strong>所以</strong>：不是现代汉语“因此”。古汉语表示“用来……的工具 / 方法；……的原因”。 <ul><li>是乃其所以千万臣而无数者也（《九方皋相马》）→ 这就是他胜过我千万倍的地方 / 原因。</li></ul></li><li><strong>所从</strong>：从哪里</li><li><strong>所由</strong>：经由的途径</li></ul><h3 id="_4-所-形容词" tabindex="-1">4. 所 + 形容词</h3><p>少见，形容词活用为动词。所贵：看重的东西。</p><h2 id="二、语法功能" tabindex="-1">二、语法功能</h2><p>所字结构在句中当名词用。</p><ol><li><p><strong>作主语</strong></p><blockquote><p>先日所用，今或弃之（《鲁施氏有二子》）</p></blockquote><p>原先被采用的（道术），现在或许舍弃。「所用」作主语。</p></li><li><p><strong>作宾语</strong></p><blockquote><p>羡施氏之有（《鲁施氏有二子》）</p></blockquote><p>“有”活用为动词，所有 = 拥有的财富。羡：羡慕，宾语是“施氏之所有”。</p></li><li><p><strong>作定语</strong></p><p>后面加名词，格式是「所V + 之 + 名词」。</p><blockquote><p>所食之粟：吃的粮食 所居之屋：居住的房屋</p></blockquote><p>此时“所V”修饰名词，“所”指代这个名词。</p></li></ol><h2 id="三、关键特点" tabindex="-1">三、关键特点</h2><ol><li><p><strong>所字结构自带被动意味</strong></p><p><code>所V</code> 大多是“被V的事物”。</p><blockquote><p>所用：被使用的东西（不是“去使用的人”）</p></blockquote><p>对比：用者 = 使用的人。</p></li><li><p><strong>动词前有施事者时，用介词“与 / 以”引出</strong></p><blockquote><p>所与共担纆薪菜者：「与」是介词，和（我）。</p></blockquote><p>所与V：和……一起做某事的人。</p></li><li><p><strong>所字结构不能单独作谓语</strong>（因为是名词性）</p><ul><li>所见甚多。（所见：主语）</li><li>吾所见：不能直接当谓语，谓语要用判断句，如“是吾所见也”。</li></ul></li></ol><h2 id="四、所字结构与者字结构" tabindex="-1">四、所字结构与者字结构</h2><table tabindex="0"><thead><tr><th>结构</th><th>格式</th><th>含义</th><th>侧重点</th></tr></thead><tbody><tr><td><strong>所字结构</strong></td><td>所 + 动词</td><td>所V的<strong>事物</strong>（受事，被动作作用的对象）</td><td><strong>动作的对象</strong></td></tr><tr><td><strong>者字结构</strong></td><td>动词 + 者</td><td>V的<strong>人</strong>（施事，发出动作的人）</td><td><strong>动作发出者</strong></td></tr></tbody></table><ul><li>见者：看见的人（发出“看”的人，者字结构）</li><li>所见：看见的事物（被看到的东西，所字结构）</li><li><strong>所见者</strong> = 所看见的东西（所 + V + 者，“者”复指）</li></ul><h2 id="五、课文例句" tabindex="-1">五、课文例句</h2><ol><li><p><strong>所业亦同</strong>（《鲁施氏有二子》）</p><blockquote><p>所业：所学的东西。所 + 动词“业”（治学），名词性短语。</p></blockquote></li><li><p><strong>所务兵食而已</strong>（《鲁施氏有二子》）</p><blockquote><p>所务：所致力的事务。主语。</p></blockquote></li><li><p><strong>子所使求马者</strong>（《九方皋相马》）</p><blockquote><p>所使：所派遣（的人）。所 + 动词“使”；后面再加“者”。所使求马者：被派去找马的人。</p></blockquote></li><li><p><strong>若皋之所观，天机也</strong>（《九方皋相马》）</p><blockquote><p>所观：所观察到的（东西、本质）。主语。</p></blockquote></li></ol><h2 id="六、简答背诵" tabindex="-1">六、简答背诵</h2><blockquote><p>“所”是特殊指示代词，置于动词或动词性词组前，构成<strong>所字结构</strong>，整体为名词性短语，在句中充当主语、宾语、定语，表示“……的人 / 事物 / 地方”；多含被动意味，指代动作的对象。常和“者”配合使用。</p></blockquote>',30)])])}const c=o(r,[["render",p]]);export{b as __pageData,c as default};
